// diun calls on every new image it sees; they wait here until Sunday instead of one alert each.
const s = $getWorkflowStaticData('global');
s.actualizaciones = s.actualizaciones || {};
for (const { json } of $input.all()) {
  const b = json.body || json;
  if (b.status !== 'update') continue;  // 'new' is diun's first look at an image, not news
  s.actualizaciones[b.image] = b.metadata?.ctn_names || b.image;
}
return [];

const get = name => { try { const j = $(name).first().json; return j.error ? null : j; } catch { return null; } };
const fin = get('Finanzas'), rec = get('Recordatorios'), dolar = get('Dólar'), pulso = get('Pulso');
const mac = get('Leer estado')?.data ?? get('Leer estado');
const dmy = d => d.slice(0, 10).split('-').reverse().slice(0, 2).join('/');
const fmt = n => '$ ' + Math.round(n).toLocaleString('es-AR');
const lines = [];

if (fin) {
  const m = fin.mes_anterior;
  if (m) {
    const verbo = m.quedo_centavos >= 0 ? 'te quedaron' : 'gastaste de más';
    lines.push(`💰 ${m.nombre[0].toUpperCase() + m.nombre.slice(1)}: ${verbo} ${m.quedo.replace('−', '')}`
      + (m.top.length ? ` (${m.top.join(', ')})` : '')
      + (m.faltan.length ? `. Faltan datos de ${m.faltan.join(', ')}` : '') + '.');
  }
  if (fin.para_revisar) lines.push(`🧾 ${fin.para_revisar} gastos para revisar en Finanzas.`);
  for (const v of fin.vencimientos || []) {
    lines.push(`💳 ${v.cuenta} vence el ${dmy(v.vence)}` + (v.total ? `: ${[v.total, v.total_usd].filter(Boolean).join(' + ')}` : '') + '.');
  }
} else lines.push('💰 Finanzas no respondió.');
if (dolar?.venta) lines.push(`💵 Dólar MEP ${fmt(dolar.venta)}.`);
if (rec?.data) lines.push(`📅 ${rec.data}`);

if (mac?.system) {
  const c = mac.containers || {}, b = mac.backup || {};
  lines.push(`🖥️ ${c.running}/${c.total} contenedores, ${mac.system.disk_free_gb} GB libres`
    + (b.last ? `, último backup ${dmy(b.last)} ${b.last.slice(11, 16)}` : '') + '.');
  if (b.last && Date.now() - new Date(b.last) > 2 * 864e5) lines.push('⚠️ El backup tiene más de 2 días.');
  if (c.down?.length) lines.push(`⚠️ Caídos: ${c.down.join(', ')}.`);
  // restore-drill.sh, Sundays at 5:00: did a test restore of last night's backup work?
  const d = mac.simulacro, r = d?.repos?.[0];
  if (!d || Date.now() - new Date(d.fecha) > 8 * 864e5) lines.push('⚠️ No hubo simulacro de restauración esta semana (setup/restore-drill.sh).');
  else if (!d.ok) lines.push(`⚠️ El simulacro de restauración falló: ${d.problemas.join('; ')}.`);
  else lines.push(`🛟 Backup probado: volvieron ${r.sqlite.ok}/${r.sqlite.total} bases y ${r.archivos.ok} archivos al azar, Finanzas arrancó con ${r.finanzas.movimientos} movimientos`
    + (d.repos.length > 1 ? ', también desde la copia externa.' : '.'));
  if (d && !d.offsite) lines.push('⚠️ Sin copia fuera de casa: si se pierde el Mac, se pierde el backup.');
  if (mac.caidas_7d?.length) lines.push(`📉 Cortes en la semana: ${mac.caidas_7d.map(x => `${x.servicio} ${x.caidas}`).join(', ')}.`);
  // Pulso (pulso/): the week minute by minute, from inside the house.
  if (pulso) {
    const min = m => m < 60 ? `${m} min` : `${Math.floor(m / 60)} h ${m % 60} min`;
    const net = pulso.internet_cortes_7d ? `${pulso.internet_cortes_7d} corte${pulso.internet_cortes_7d > 1 ? 's' : ''} de internet (${min(pulso.internet_min_caido_7d)})` : 'internet sin cortes';
    const luz = pulso.cortes_luz_7d ? `${pulso.cortes_luz_7d} corte${pulso.cortes_luz_7d > 1 ? 's' : ''} de luz (${min(pulso.min_sin_luz_7d)})` : 'sin cortes de luz';
    const v = pulso.velocidad_7d;
    lines.push(`📈 ${net}, ${luz}.` + (v ? ` Velocidad: ${v.bajada}/${v.subida ?? '?'} Mbit/s promedio, la peor bajada ${v.bajada_min}.` : ''));
    const crashed = Object.entries(pulso.contenedores_caidos_7d || {});
    if (crashed.length) lines.push(`💥 Contenedores con problemas: ${crashed.map(([n, c]) => `${n} ${c}`).join(', ')} (detalle en Pulso).`);
    if (pulso.disco && !pulso.disco.startsWith('pronóstico')) lines.push(`💽 Disco: ${pulso.disco}.`);
  }
} else lines.push('🖥️ No pude leer el estado del Mac (setup/n8n-feed.sh).');

const s = $getWorkflowStaticData('global');
const ups = [...new Set(Object.values(s.actualizaciones || {}))];
if (ups.length) lines.push(`⬆️ Hay versión nueva de ${ups.join(', ')}: se actualizan solas el 1° a las 4:30.`);
s.actualizaciones = {};

return [{ json: { resumen: lines.join('\n') } }];

const resumen = $('Armar resumen').first().json.resumen;
const ia = ($input.first().json.message?.content || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
return [{ json: {
  title: 'Resumen de la semana', message: resumen + (ia ? `\n\n💬 ${ia}` : ''),
  tag: 'calendar', click: 'https://mac-server.tailnet-ejemplo.ts.net:3013/mes',
} }];
